<?php
if(!isset($shown,$user)||!$user){http_response_code(404);exit;}
if($view!=='overview'){
 $search=query_text('q');if($search!=='')$shown=array_values(array_filter($shown,fn($r)=>stripos($r['name'].' '.$r['leave_type'].' '.$r['status'].' #'.$r['id'],$search)!==false));
 $key=query_text('sort',$view==='approved'?'start_date':'created_at');if(!in_array($key,['id','name','leave_type','start_date','end_date','duration','status','created_at'],true))$key='created_at';$dir=query_text('dir',$view==='approved'?'asc':'desc')==='asc'?1:-1;
 usort($shown,function($a,$b)use($key,$dir){$av=$key==='duration'?leave_duration($a):$a[$key];$bv=$key==='duration'?leave_duration($b):$b[$key];return $dir*(($av<=>$bv)?:($a['id']<=>$b['id']));});
?>
<form method="get" class="table-tools"><input type="hidden" name="view" value="<?= e($view) ?>"><input type="hidden" name="status" value="<?= e(query_text('status',$admin?'Pending':'')) ?>"><label>Search Requests<input name="q" maxlength="100" value="<?= e(query_text('q')) ?>" placeholder="Name, type, or status"></label><button class="button">Search</button><a class="button button-secondary" href="index.php?view=<?= e($view) ?>">Reset</a></form>
<?php } ?>
<?php if(!$shown):?><div class="empty"><h3>No requests to show.</h3><p>Try another filter or search.</p></div><?php else:?>
<div class="table-scroll" role="region" aria-label="Leave requests" tabindex="0"><table class="data-table"><caption><?= count($shown) ?> leave requests · Monday–Friday only</caption><thead><tr>
<?php foreach(['id'=>'Request','name'=>'Employee','leave_type'=>'Type','start_date'=>'Start','end_date'=>'End','duration'=>'Days','status'=>'Status'] as $key=>$label): if($key==='name'&&!$admin)continue; ?><th scope="col"><?= $view==='overview'?e($label):sort_link($key,$label) ?></th><?php endforeach ?><th scope="col">Timing &amp; Details</th></tr></thead><tbody>
<?php foreach($shown as $r):?><tr><td>#<?= (int)$r['id'] ?></td><?php if($admin):?><td><?= e($r['name']) ?></td><?php endif ?><td><?= e(leave_label($r['leave_type'])) ?></td><td><?= e($r['start_date']) ?></td><td><?= e($r['end_date']) ?></td><td><?= leave_duration($r) ?></td><td><span class="badge <?= strtolower($r['status']) ?>"><?= e($r['status']) ?></span></td><td><b class="leave-timing"><?= e(leave_timing($r)) ?></b><details><summary>View Details</summary><p class="reason"><?= nl2br(e($r['reason'])) ?></p><small>Submitted <?= e($r['created_at']) ?></small>
<?php if($r['reviewed_at']):?><p><?= e($r['status']) ?> by <?= e($r['reviewer']) ?> · <?= e($r['reviewed_at']) ?></p><p><?= nl2br(e($r['remarks'])) ?></p><?php endif ?>
<?php if($r['status']==='Pending'&&$view==='requests'): if($admin):?><form method="post" class="review-form"><?= csrf() ?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label>Remarks (optional)<textarea name="remarks" maxlength="1000" rows="2"></textarea></label><div class="button-group"><button class="button" name="status" value="Approved">Approve ✓</button><button class="button danger" name="status" value="Rejected">Reject</button></div></form><?php else:?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="cancel">Cancel Request</button></form><?php endif;endif ?></details></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
